package main

import (
	"fmt"
	"log"
	"net/http"
)

// Hello handler function for /hello endpoint with both GET and POST methods.
func hello(w http.ResponseWriter, r *http.Request) {
	if r.Method == "GET" || r.Method == "HEAD" {
		fmt.Fprintf(w, "<h1>Hello World - %s</h1>", r.URL.Path[1:])
	} else if r.Method == "POST" {
		body := []byte("This is a post request")
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		w.WriteBody(body)
	} else {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
	}
}

// DataPost handler function for /api/data endpoint handling only POST method.
func dataPost(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	r.ParseForm() // Parse form values from URL query string or body content.
	name := r.FormValue("name")
	message := fmt.Sprintf("<p>You said your name was '%s'.</p>", name)
	w.Write([]byte(message))
}

func main() {
	router := http.NewServeMux()

	// Register handlers for different routes and methods.
	router.HandleFunc("/hello/{path:.*}", hello)
	router.HandleFunc("/api/data", http.StripPrefix("/api", http.FileServer(http.Dir("."))).Lazy(), nil)
	router.HandleFunc("/api/data", func(rw http.ResponseWriter, req *http.Request) {
		dataPost(rw, req)
	})

	// Start the server on port 8080 by default but can be changed via environment variable.
	port := ":8080"
	addr := ":" + port[1:]

	println(fmt.Sprintf("Starting server at %s...\n", addr))
	err := http.ListenAndServe(addr, router)
	if err != nil {
		panic(err.Error())
	}
}
```

